    start4: 'Trước pha bóng đầu tiên của mỗi ván vẫn sửa được: bấm "… giao trước" để đổi đội giao, "Đổi vị trí …" nếu 2 người đứng ngược.',
    tapTitle: 'Trong lúc đánh',
    tap1: "Mỗi khi một pha bóng kết thúc, bấm vào khung của đội THẮNG pha đó — kể cả khi đội đó không được điểm. Điểm, tay giao và quyền giao được tự cập nhật.",
    tap2: 'Khung có viền xanh và nhãn "Giao bóng" là đội đang giao; biểu tượng vợt / cầu nằm cạnh tên người đang giao, kèm ô Phải/Trái họ phải đứng.',
    tap3: 'Trước mỗi quả giao, đọc to dòng "Đọc điểm" ở giữa màn hình để hai đội cùng nghe.',
    tap4: 'Làm theo dòng nhắc: Đổi quyền giao bóng, Chuyển người giao thứ 2, Đổi sân, Nghỉ giữa ván. Nhãn đỏ Game point / Match point báo đội sắp thắng ván / trận.',
    tap5: 'Bấm nút Sửa cạnh tên sân để sửa sân. Có thể mở trang này trên 2 máy; điểm luôn đồng bộ.',
    fixTitle: 'Khi bấm nhầm',
    fix1: 'Bấm ↶ Hoàn tác để lùi đúng 1 pha; bấm nhiều lần để lùi nhiều pha. Người giao, vị trí và điểm trở lại như cũ.',
    fix2: "Nếu thấy thông báo \"Có người khác vừa bấm điểm\": máy khác đã bấm trước và điểm mới nhất đã được tải lại. Kiểm tra rồi bấm lại pha của bạn nếu còn thiếu.",
    fix3: '■ Dừng là huỷ việc bấm điểm trận này (không lưu gì vào giải) — chỉ dùng khi trận bị hoãn hoặc mở nhầm trận.',
    endTitle: 'Khi hết trận',
    end1: "Trận tự kết thúc khi đủ điểm (cách 2 điểm) và hiện \"… thắng trận\".",
    end2: 'Kiểm tra điểm từng ván ở dòng trên cùng, rồi bấm Lưu kết quả vào giải. Chưa bấm lưu thì kết quả CHƯA vào bảng đấu.',
    end3: 'Sau khi lưu, tỷ số vào bảng / nhánh đấu như nhập tay và đội thắng tự vào vòng sau. Quay lại danh sách để bấm trận tiếp theo.',
    callTitle: 'Câu đọc điểm pickleball (đánh đôi):',
    callServing: 'điểm đội đang giao',
    callReceiving: 'điểm đội nhận',
    callServer: 'tay giao (1 hoặc 2)',
    pbTitle: 'Luật tính điểm pickleball (tính điểm khi giao)',
    pb1: 'Chỉ đội đang giao bóng mới được cộng điểm. Đội nhận thắng pha bóng thì không được điểm, chỉ lấy lại quyền giao.',
    pb2: 'Đánh đôi: mỗi đội có 2 lượt giao (tay 1 và tay 2). Riêng lượt giao đầu tiên của ván chỉ có 1 tay, nên ván bắt đầu bằng 0-0-2.',
    pb3: 'Đội giao thắng pha: +1 điểm, người giao đổi ô với đồng đội và giao tiếp (từ ô bên kia).',
    pb4: 'Đội giao thua pha: nếu đang tay 1 → đồng đội giao (tay 2); nếu đang tay 2 → đổi quyền giao sang đội kia, người đứng ô PHẢI của đội đó giao trước (tay 1).',
    pb5: 'Đánh đơn: điểm của người giao chẵn thì giao từ ô phải, lẻ từ ô trái; thua pha là đổi quyền giao ngay.',
    pb6: 'Ván đến 11 điểm (hoặc 15 / 21), phải hơn 2 điểm. Thắng 2/3 ván: ván sau đội nhận ở ván trước sẽ giao trước.',
    pb7: 'Ván quyết định: khi một đội chạm nửa số điểm (6 với ván 11, 8 với ván 15) hai đội đổi sân, điểm giữ nguyên.',
    pbExampleTitle: 'Ví dụ',
    pbExample: 'Bắt đầu 0-0-2, đội A giao. A thắng → 1-0-2 (người giao A đổi ô). A thua → đổi giao: B giao 0-1-1. B thua → 0-1-2 (đồng đội B giao). B thắng → 1-1-2. B thua → đổi giao: A giao 1-1-1.',
    courtTitle: 'Giao từ ô nào (nhìn từ phía người giao):',
    net: '— lưới —',
    odd: 'điểm lẻ',
    even: 'điểm chẵn',
    serverView: 'người giao đứng ở đây',
    bmTitle: 'Luật tính điểm cầu lông (rally)',
    bm1: 'Pha bóng nào cũng có điểm: đội thắng pha được +1 và giành / giữ quyền giao.',
    bm2: 'Điểm của đội giao chẵn (0, 2, 4…) thì giao từ ô PHẢI, lẻ thì từ ô TRÁI.',
    bm3: 'Đánh đôi: đội giao thắng pha thì người giao đổi ô với đồng đội và giao tiếp; đội nhận không đổi chỗ. Khi giành lại quyền giao, người đứng đúng ô (chẵn phải / lẻ trái) giao.',
    bm4: 'Ván 21 điểm, phải hơn 2 điểm; 29-29 thì ai được điểm thứ 30 thắng ván (các thể thức khác xem bên dưới).',
    bm5: 'Nghỉ ngắn khi đội dẫn chạm nửa số điểm (11 với ván 21); hết mỗi ván hai đội đổi sân; ván quyết định đổi sân thêm ở nửa ván.',
    bm6: 'Đội thắng ván trước giao trước ở ván sau. Trận thắng 2/3 ván.',
    bmExampleTitle: 'Ví dụ',
    bmExample: 'A giao 0-0 từ ô phải. A thắng → 1-0, người giao A đổi sang ô trái, giao tiếp. B thắng → 1-1, B giao; điểm B lẻ (1) nên người đứng ô TRÁI của B giao. B thắng → 2-1 (B), người giao đổi sang ô phải.',
