    unsaved: "Có thay đổi chưa lưu",
    rankTitle: "Bảng xếp hạng",
    rankHint: "Bảng xếp hạng của cộng đồng (trang Bảng xếp hạng của bạn và trang cộng đồng của người chơi) luôn có tab Toàn cộng đồng. Chọn thêm cách chia tab bên dưới; mỗi tab chỉ xếp hạng những người thuộc tab đó.",
    rank_none: "Chỉ toàn cộng đồng",
